package com.gfilmes.server
import org.junit.Assert.*
import org.junit.Test
import java.net.*
import java.util.concurrent.CopyOnWriteArrayList

class SetupPortalTest {
 private val token="a".repeat(64)
 private fun key()=java.util.Base64.getUrlEncoder().withoutPadding().encodeToString(java.security.KeyPairGenerator.getInstance("RSA").apply{initialize(2048)}.generateKeyPair().public.encoded).toByteArray()
 private fun request(port:Int,path:String,method:String="GET",data:ByteArray?=null,origin:String?=null):Pair<Int,ByteArray>{val c=URL("http://127.0.0.1:$port/$path").openConnection() as HttpURLConnection;c.connectTimeout=2000;c.readTimeout=2000;c.requestMethod=method;if(origin!=null)c.setRequestProperty("Origin",origin);if(data!=null){c.doOutput=true;c.setFixedLengthStreamingMode(data.size);c.outputStream.use{it.write(data)}};try{val status=c.responseCode;return status to (if(status>=400)c.errorStream else c.inputStream).use{it.readBytes()}}finally{c.disconnect()}}
 @Test fun keyDownloadAndOnlyExplicitSignedFileRoutesAreExposed(){val pub=key();val files=CopyOnWriteArrayList<String>();SetupPortal(InetAddress.getLoopbackAddress(),0,token,pub,{kind,bytes->files.add(kind+":"+String(bytes))}).use{p->p.start();assertEquals(404,request(p.port,"wrong/public-key").first);val actual=request(p.port,"$token/public-key");assertEquals(200,actual.first);assertArrayEquals(pub,actual.second);val html=String(request(p.port,"$token/").second);assertTrue(html.contains("/"+token+"/public-key"));assertFalse(html.contains("type=\"password\""));assertEquals(404,request(p.port,"$token/api/auth/login","POST","{}".toByteArray()).first);assertEquals(200,request(p.port,"$token/grant","POST","signed-fixture".toByteArray()).first);assertEquals(listOf("grant:signed-fixture"),files.toList())}}
 @Test fun badTokenCrossOriginOversizeAndRejectedSignatureDoNotImport(){val files=CopyOnWriteArrayList<String>();SetupPortal(InetAddress.getLoopbackAddress(),0,token,key(),{kind,bytes->if(String(bytes)=="bad")error("invalid signature");files.add(kind)},maxBody=1024).use{p->p.start();assertEquals(404,request(p.port,"b".repeat(64)+"/migration","POST","sealed".toByteArray()).first);assertEquals(413,request(p.port,"$token/migration","POST",ByteArray(2048)).first);assertEquals(400,request(p.port,"$token/migration","POST","bad".toByteArray()).first);assertTrue(files.isEmpty());val socket=Socket("127.0.0.1",p.port);socket.use{s->s.soTimeout=2000;s.getOutputStream().write(("POST /$token/migration HTTP/1.1\r\nHost: localhost\r\nOrigin: https://evil.example\r\nContent-Length: 1\r\n\r\nx").toByteArray());val reply=s.getInputStream().bufferedReader().readText();assertTrue(reply.startsWith("HTTP/1.1 403"))};assertTrue(files.isEmpty())}}
 @Test fun backupIsUnavailableUntilAnEncryptedExportIsPrepared(){SetupPortal(InetAddress.getLoopbackAddress(),0,token,key(),{_,_->}).use{p->p.start();assertEquals(404,request(p.port,"$token/backup").first)};val cipher="encrypted fixture".toByteArray();SetupPortal(InetAddress.getLoopbackAddress(),0,token,key(),{_,_->},{cipher}).use{p->p.start();assertArrayEquals(cipher,request(p.port,"$token/backup").second)}}
 @Test fun duplicateLengthAndChunkedRequestsAreClosed(){SetupPortal(InetAddress.getLoopbackAddress(),0,token,key(),{_,_->fail("must not import")}).use{p->p.start();for(extra in listOf("Content-Length: 1\r\nContent-Length: 1","Content-Length: 1\r\nTransfer-Encoding: chunked")){Socket("127.0.0.1",p.port).use{s->s.soTimeout=2000;s.getOutputStream().write(("POST /$token/migration HTTP/1.1\r\nHost: localhost\r\n$extra\r\n\r\nx").toByteArray());assertTrue(s.getInputStream().bufferedReader().readText().startsWith("HTTP/1.1 400"))}}}}
}
